#!/usr/bin/env bash
# HERO_MOCKUP deploy — kokpit2 "Nakit hikayesi" bolumu mockup grid2'ye (DSO uc yuzu + kim tasiyor).
#   FRONTEND-ONLY: yalniz shells/kokpit2.html degisir. Server route'lari aynen. CANLI /api/bi/kokpit'e DOKUNMAZ.
set -e
cd /opt/krb-assessment
KOKF=shells/kokpit2.html
[ -f "$KOKF" ] || { echo "HATA: $KOKF yok"; exit 1; }
cp "$KOKF" "$KOKF.bak.$(date +%s)"
printf '%s' '' | base64 -d > "$KOKF"
echo "kokpit2.html satir: $(wc -l < "$KOKF")"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== ONIZLE: /api/bi/kokpit2 -> Nakit hikayesi artik iki temiz panel (DSO uc yuzu + kim tasiyor) =="
echo "== DONE =="
